ct-image img{height:100%;object-fit:contain;transition:transform .5s}.project-image:hover img{transform:scale(1.025)}.rag-image{background:#e8e4de;border-color:#ded6cd}.image-index{position:absolute;left:20px;top:17px;font-family:var(--mono);font-size:9px;letter-spacing:1px;color:#53634e}.image-arrow{position:absolute;right:16px;bottom:16px;width:31px;height:31px;display:grid;place-items:center;background:rgb(255 255 255 / 70%)}.project-meta{display:flex;justify-content:space-between;gap:12px;font-family:var(--mono);font-size:8px;letter-spacing:1px;color:var(--muted);margin-top:22px}.project-meta>span:last-child{color:var(--accent)}.project h3{margin-top:11px;font-size:23px;font-weight:500}.project h3 a{display:flex;align-items:center;justify-content:space-between;gap:12px}.project h3 a svg{width:18px}.project>p{margin-top:14px;font-size:13px;line-height:1.85;color:var(--muted);max-width:490px}.tags{display:flex;flex-wrap:wrap;gap:7px;margin:18px 0 0}.tags li{padding:4px 9px;border:1px solid #cfd7cb;font-family:var(--mono);font-size:9px;color:#4e5e4d}.work-footnote{font-size:10px;color:var(--muted);margin-top:36px;padding-top:20px;border-top:1px solid #d5ddcf}.section-space{padding-block:79px}.section-aside{font-size:11px;color:var(--muted);margin-bottom:6px}.experience-row{display:grid;grid-template-columns:260px 1fr;gap:40px;padding:36px 0;border-top:1px solid var(--line)}.experience-company h3{font-size:25px}.experience-company p{font-size:11px;color:var(--muted);margin-top:10px}.experience-company>.small-label{display:block;font-size:8px;margin-top:18px;color:var(--muted)}.experience-detail h4{font-size:21px;margin-bottom:15px}.experience-detail>p{font-size:13px;color:var(--muted);max-width:690px;line-height:1.85}.experience-detail>ul:not(.tags){margin:20px 0 0}.experience-detail>ul:not(.tags) li{padding-left:17px;position:relative;font-size:12px;color:var(--muted);margin:9px 0;line-height:1.8}.experience-detail>ul:not(.tags) li:before{content:'+';position:absolute;left:0;color:var(--green)}.impact-strip{display:grid;grid-template-columns:repeat(3,1fr);margin-top:27px;padding:22px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:20px}.impact-strip>div{display:flex;flex-direction:column}.impact-strip strong{font-family:var(--serif);font-size:35px;line-height:1.2;font-weight:400}.impact-strip strong>span{font-size:24px;color:var(--green)}.impact-strip>div>span{font-size:10px;color:var(--muted);margin-top:5px}.cloud-row{padding-bottom:0}.publication{padding-block:52px}.publication-layout{display:grid;grid-template-columns:260px 1fr;gap:40px}.publication .eyebrow{color:var(--muted)}.publication-venue{display:block;font-size:11px;margin-top:16px;color:var(--green)}.publication h2{font-size:33px;line-height:1.25}.publication h2 em{color:var(--green)}.publication-layout>div>p:not(.eyebrow){font-size:13px;color:var(--muted);max-width:600px;margin-top:17px;line-height:1.8}.publication-bottom{display:flex;justify-content:space-between;align-items:center;gap:22px;margin-top:23px}.publication-bottom>span{font-size:10px;color:var(--muted)}.publication-bottom strong{font-size:16px;font-weight:550;color:var(--green);margin-right:5px}.about{display:grid;grid-template-columns:1.25fr 1fr;gap:100px}.about h2{font-size:34px;line-height:1.25;margin-top:18px}.about h2 em{color:var(--green)}.about-copy{font-size:13px;color:var(--muted);line-height:1.9;margin-top:21px}.social-links{display:flex;gap:26px;margin-top:25px}.social-links svg{width:15px}.education{border-left:1px solid var(--line);padding-left:40px}.education>h3{color:var(--muted);margin-bottom:23px}.education>div+div{margin-top:25px;padding-top:24px;border-top:1px solid var(--line)}.education-year{font-family:var(--mono);font-size:10px;color:var(--muted)}.education h4{font-size:16px;margin-top:8px;line-height:1.5}.education p{font-size:12px;margin-top:4px;color:var(--muted)}.grade{display:inline-block;font-family:var(--mono);font-size:9px;color:var(--green);margin-top:11px}.contact{background:var(--ink);color:var(--paper);padding:51px 0 25px}.contact .eyebrow{color:#b6c3b4}.contact-heading{display:flex;align-items:center;justify-content:space-between;margin-top:20px;gap:20px}.contact h2{font-size:46px;line-height:1.2}.contact h2 em{color:#bacdb2}.contact-arrow{display:grid;place-items:center;width:72px;height:72px;border:1px solid #737f70;border-radius:50%;transition:background .2s}.contact-arrow:hover{background:#465342}.contact-arrow svg{width:34px;height:34px}.email{display:inline-block;font-size:16px;margin-top:23px;border-bottom:1px solid #7d8c76;padding-bottom:3px;overflow-wrap:anywhere}.contact-bottom{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #485345;padding-top:22px;margin-top:38px;font-size:10px;color:#b8c2b3}.contact-bottom a{display:flex;align-items:center;gap:10px}.contact-bottom svg{width:14px;height:14px}.footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:25px}.footer .wordmark{font-size:28px}.footer>span{font-size:10px;color:var(--muted)}.footer>a:last-child{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--muted)}.footer svg{width:14px}.reveal{animation:appear .65s ease both}@keyframes appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
