pany>.small-label{margin:0;font-size:8px;grid-column:1/-1}.experience-detail h4{font-size:19px;margin-bottom:12px}.experience-detail>p{font-size:12px}.experience-detail>ul:not(.tags) li{font-size:11px}.impact-strip{gap:13px;padding-block:19px;margin-top:22px}.impact-strip strong{font-size:30px}.impact-strip>div>span{font-size:9px;line-height:1.6;max-width:90px}.cloud-row{padding-bottom:0}.publication{padding-block:36px}.publication-layout{grid-template-columns:1fr;gap:25px}.publication-venue{margin-top:10px;font-size:10px}.publication h2{font-size:29px}.publication-layout>div>p:not(.eyebrow){font-size:12px}.publication-bottom{gap:15px;margin-top:18px}.about{grid-template-columns:1fr;gap:35px}.about h2{font-size:29px}.about-copy{font-size:12px}.education{border-left:0;border-top:1px solid var(--line);padding:25px 0 0}.education h4{font-size:15px}.contact{padding-top:36px}.contact h2{font-size:33px}.contact-arrow{width:50px;height:50px;flex-shrink:0}.contact-arrow svg{width:26px;height:26px}.email{font-size:15px}.contact-bottom{font-size:9px;gap:15px;align-items:flex-start}.contact-bottom>span{max-width:150px}.contact-bottom a{gap:7px}.footer{padding-block:20px;gap:12px}.footer>span{font-size:9px}.footer>a:last-child{font-size:9px;gap:4px}}
