if (window.lucide) {
  window.lucide.createIcons();
}

document.getElementById('year').textContent = new Date().getFullYear();

const navigationLinks = document.querySelectorAll('nav a');
const sectionObserver = new IntersectionObserver((entries) => {
  for (const entry of entries) {
    if (entry.isIntersecting) {
      for (const link of navigationLinks) {
        const isCurrent = link.hash === `#${entry.target.id}`;
        link.classList.toggle('active', isCurrent);
        if (isCurrent) {
          link.setAttribute('aria-current', 'location');
        } else {
          link.removeAttribute('aria-current');
        }
      }
    }
  }
}, { rootMargin: '-15% 0px -45% 0px' });

for (const link of navigationLinks) {
  const section = document.querySelector(link.hash);
  if (section) sectionObserver.observe(section);
}

const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');

if (!motionPreference.matches) {
  document.querySelector('.intro').classList.add('reveal');

  const description = document.getElementById('intro-description');
  const fullText = description.textContent;
  const source = document.createElement('span');
  source.className = 'intro-source';
  source.textContent = fullText;

  const generated = document.createElement('span');
  generated.className = 'intro-generated';
  generated.setAttribute('aria-hidden', 'true');
  description.replaceChildren(source, generated);
  description.classList.add('is-typing');

  let startTime;
  let animationFrame;

  function finishTyping() {
    cancelAnimationFrame(animationFrame);
    description.classList.remove('is-typing');
    generated.remove();
    motionPreference.removeEventListener('change', finishTyping);
  }

  function typeIntroduction(timestamp) {
    if (startTime === undefined) startTime = timestamp;
    const characterCount = Math.floor((timestamp - startTime) * 0.115);
    generated.textContent = fullText.slice(0, characterCount);

    if (characterCount >= fullText.length) {
      finishTyping();
    } else {
      animationFrame = requestAnimationFrame(typeIntroduction);
    }
  }

  motionPreference.addEventListener('change', finishTyping);
  animationFrame = requestAnimationFrame(typeIntroduction);
}

